*{margin:0;padding:0;box-sizing:border-box}
:root{--primary:#6c63ff;--bg:#1a1a2e;--card:#16213e;--text:#e8e8e8;--accent:#0f3460;--success:#00b894;--radius:12px}
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:var(--bg);color:var(--text);min-height:100vh}
.app-header{background:linear-gradient(135deg,var(--accent),var(--primary));padding:2rem;text-align:center;border-radius:0 0 var(--radius) var(--radius)}
.app-header h1{font-size:1.8rem;margin-bottom:0.5rem}
.subtitle{opacity:0.8;font-size:0.9rem}
.app-content{padding:1rem;max-width:600px;margin:0 auto}
.card{background:var(--card);border-radius:var(--radius);padding:1.5rem;margin:1rem 0;box-shadow:0 4px 20px rgba(0,0,0,0.3)}
.card h2{color:var(--primary);margin-bottom:1rem;font-size:1.2rem}
.feature-list{display:flex;flex-direction:column;gap:0.5rem}
.feature-item{padding:0.5rem;background:rgba(108,99,255,0.1);border-radius:8px;font-size:0.9rem}
.platform-grid{display:grid;gap:0.8rem}
.platform-item{display:flex;align-items:center;gap:1rem;padding:1rem;background:rgba(108,99,255,0.1);border-radius:8px}
.platform-item .icon{font-size:1.5rem}
.platform-item span{flex:1}
.platform-item small{color:var(--primary);font-size:0.8rem}
.app-footer{text-align:center;padding:2rem;opacity:0.5;font-size:0.8rem}
@media(min-width:480px){.platform-grid{grid-template-columns:1fr 1fr}}

